class RateLimiter:
    """Allow at most `max_calls` calls per window; thread-safe usage expected."""
    def __init__(self, max_calls):
        self.max_calls = max_calls
        self.count = 0

    def allow(self):
        """Return True if this call is allowed, False if the limit is exceeded."""
        if self.count >= self.max_calls:
            return False
        self.count += 1
        return True
